mapper.select:
select sdnc.id, sdnc.code, sdnc.source_id as noticeId, sdnc.source_code as noticeCode, sdnc.so_id as soId, sdnc.so_code as soCode, sdnc.approve_status as approveStatus, sdnc.invalid_status as invalidStatus, sdnc.customer_name as customerName, sdncd.sku_id as skuId, sdncd.sku_no as skuNo, sdncd.product_name as productName, sdncd.source_detail_id as sourceDetailId, sdncd.so_detail_id as soDetailId, sdncd.change_type as changeType, sdncd.origin_qty as originQty, sdncd.new_qty as newQty, sdncd.id as detailId, sdnc.create_user_name as createUserName, sdnc.approve_user_name as approveUserName, sdnc.create_time as createTime, sdnc.approve_time as approveTime, sdnd.picking_qty as pickedQty from so_delivery_notice_change sdnc inner join so_delivery_notice_change_detail sdncd on sdnc.id = sdncd.main_id and sdncd.is_deleted = false left join so_delivery_notice sdn on sdn.id = sdnc.source_id and sdn.is_deleted = false left join so_delivery_notice_detail sdnd on sdnd.id = sdncd.source_detail_id and sdnd.is_deleted = false where ${params.sqlMap.default} and sdnc.is_deleted = false
${params.permissionSql}
order by
${item.field} ${item.sort}
sdnc.create_time desc

SELECT sdnc.approve_status AS tabFlag, count(sdnc.id) AS count FROM so_delivery_notice_change sdnc left join so_delivery_notice sdn on sdn.id = sdnc.source_id and sdn.is_deleted = false WHERE sdnc.is_deleted=FALSE
${params.permissionSql}
GROUP BY sdnc.approve_status

select sd.id as soDetailId, sdnd.id as sourceDetailId, sd.delivery_sku_id as skuId, sd.delivery_sku_no as skuNo, sd.box_qty as saleQty, sd.bom_version as bomVersion, sd.platform_sku_no as platformSkuNo, (select COALESCE(sum(a.delivery_qty),0) from so_delivery_notice_detail a where a.source_detail_id = sd.id and a.is_deleted = false) as allNoticeQty, COALESCE(sdnd.delivery_qty,0) as currentNoticeQty, sdnd.picking_qty as pickedQty, sd.remark from so_info si inner join so_detail sd on si.id = sd.main_id and sd.is_deleted = false inner join so_delivery_notice sdn on sdn.source_id = si.id and sdn.is_deleted = false and sdn.id = #{params.noticeId} left join so_delivery_notice_detail sdnd on sdnd.is_deleted = false and sdnd.source_detail_id = sd.id and sdnd.main_id = sdn.id where ${params.sqlMap.default} and si.is_deleted = false and si.id = #{params.soId}
AND sd.delivery_sku_no IN
#{sku}
AND sdnd.id IN
#{id}
